"async function authorize(){if(authToken)return;const paired=await request('/api/pair',{method:'POST',headers:{'Content-Type':'application/json','X-Lingxi-LAN':'1'},body:JSON.stringify({mode:'lan'})});if(!paired.ok)throw Error(t('无法建立局域网连接（')+paired.status+t('）。请连接同一 Wi-Fi，等待热点关闭；旧固件请先 USB 更新。'));const result=await paired.json();if(!/^[0-9a-f]{16}$/i.test(result.token||''))throw Error(t('设备连接响应无效'));authToken=result.token;}\n"
"async function configurationRequest(save,body){await authorize();const r=await request('/api/standalone',{method:save?'PUT':'GET',headers:{Authorization:'Bearer '+authToken,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});\n"
"if(!r.ok){if(r.status===500){const failure=await r.json().catch(()=>({}));throw Error(t(failure.reason==='low_memory'?'设备内存不足，配置未保存；请稍后重试':failure.reason==='storage_full'?'设备配置存储空间不足，原配置保留':'设备配置写入失败（500），原配置保留；请更新 C6 固件后重试'));}if(r.status===401){authToken='';cfg=null;clearSecrets();}const failure=Error(t(r.status===409?'配置已在软件或其他入口更新。请重新读取后再修改；未覆盖设备原配置。':r.status===401?'连接已失效，请重新读取配置':r.status===400?'设备拒绝配置，请检查服务器、实体和凭据内容':'操作未完成：')+(r.status===400||r.status===401||r.status===409?'':r.status));failure.conflict=r.status===409;throw failure;}\n"
"const result=await r.json();if(result.schema_version!==2)throw Error(t('请先通过 USB 更新到支持独立运行的 C6 固件'));return result;}\n"
"// One transaction at a time. An old response never replaces newer user edits.\n"
"class AutoSave {\n"
"    constructor(save,report){this.save=save;this.report=report;this.sequence=0;this.pending=false;this.running=false;this.composing=false;this.blocked=false;}\n"
"    change(){this.sequence++;this.pending=true;clearTimeout(this.timer);if(!this.blocked&&!this.composing)this.timer=setTimeout(()=>this.flush(),800);}\n"
"    async flush(){clearTimeout(this.timer);if(this.running||this.composing||this.blocked||!this.pending)return;\n"
"        const sequence=this.sequence;this.running=true;this.pending=false;\n"
"        try{await this.save(sequence);}catch(e){this.pending=true;this.blocked=e.conflict===true;this.report(e);return;}\n"
"        finally{this.running=false;}if(this.pending&&!this.blocked)this.timer=setTimeout(()=>this.flush(),250);\n"
"    }\n"
"    reset(){clearTimeout(this.timer);this.pending=false;this.blocked=false;}\n"
"}\n"
"\n"
"let manualSave=false;\n"
"// A save acknowledgement updates bookkeeping, never the live form DOM. In\n"
"// particular, don't replace a select/checkbox or restore an earlier focus.\n"
"function acceptSaved(result){cfg=clean(result);savedCfg=clone(cfg);clearSecrets();el('haCredentialState').textContent=t(cfg.ha.token_set?'设备已保存令牌；不更换服务器时留空保留。':'设备尚未保存令牌，启用直连前请填写。');for(const [i,p]of cfg.printers.entries()){el('p_brandlabel_'+i).textContent=(p.source_formlabs?'Formlabs':'Bambu Lab')+' · '+(p.name||t('打印机 ')+(i+1));translatedText(el('p_form_secret_'+i+'_help'),p.form_credentials_set?'同一打印机与 Client ID 留空保留；凭据保存在设备中':'复用 Dashboard 云端 API 凭据，需联网；OAuth Token 仅缓存在内存');translatedText(el('p_code_'+i+'_help'),p.access_code_set?'设备已保存；同一打印机留空保留':'在打印机 LAN 模式中获取');}el('json').textContent=JSON.stringify(savedCfg,null,2);if(typeof previewOptions==='function')previewOptions(savedCfg);}\n"
"const autosave=new AutoSave(async sequence=>{\n"
"if(busy){autosave.pending=true;return;}const force=manualSave;manualSave=false;let body;try{body=collect();}catch(e){e.focusField=force;throw e;}const key=fingerprint(body);\n"
"if(!force&&key===lastSavedFingerprint){dirty=false;status('已保存 · 设置自动应用','success');updateControls();return;}\n"
"saving=true;busy=true;updateControls();status('正在保存全部设置…');\n"
"try{const result=await configurationRequest(true,body);if(!portalAlive)return;if(sequence===autosave.sequence){dirty=false;acceptSaved(result);lastSavedFingerprint=fingerprint(collect());status('已保存 · 设置自动应用','success');}\n"
"else{cfg.revision=result.revision;savedCfg=clean(result);dirty=true;autosave.pending=true;}}\n"
"finally{saving=false;busy=false;if(portalAlive){updateControls();health();setTimeout(()=>refreshPreview(true),300);}}},e=>{status(e.message,'error');if(e.focusField&&e.field)focusInvalidField(e.field);updateControls();});\n"
"async function transfer(save){if(save){if(autosave.running)return;manualSave=true;autosave.pending=true;return autosave.flush();}if(busy)return;if(dirty&&!confirm(t('重新读取将替换尚未保存的更改，继续吗？')))return;autosave.reset();busy=true;updateControls();status('正在连接设备…');\n"
"try{const result=await configurationRequest(false);if(!portalAlive)return;dirty=false;fill(result);clearSecrets();try{lastSavedFingerprint=fingerprint(collect());}catch{lastSavedFingerprint='';}status(t('已读取设备配置')+' · '+t('修订 ')+cfg.revision,'success');await health();refreshPreview(true);}\n"
"catch(e){if(portalAlive)status(e.message,'error');}finally{busy=false;if(portalAlive)updateControls();}}\n"
"async function health(){if(!authToken)return;try{const r=await request('/api/health',{headers:{Authorization:'Bearer '+authToken}});if(!r.ok)throw Error();const result=await r.json();if(result.snapshot_available===false)throw Error();healthSnapshot=result;renderHealth(result);}catch{translatedText(el('health'),'连接状态暂不可读取，保存成功不代表数据源连接成功。');}}\n"
"function renderHealth(result){const box=el('health');box.replaceChildren();for(const p of result.printers||[]){const row=document.createElement('div');row.className='health-row';const name=document.createElement('span');name.textContent=(p.brand==='formlabs'?'Formlabs':'Bambu Lab')+' · '+(p.name||p.serial);const detail=document.createElement('small');detail.textContent=p.serial;name.append(detail);const value=document.createElement('span'),phases={waiting:'等待联网',connected:'已连接',retrying:'正在重试',auth_rejected:'凭据被拒绝',low_memory:'等待内存'};value.textContent=t(phases[p.phase]||'等待数据')+' · '+printState(p.status)+(p.connected&&p.progress_valid!==false?' · '+p.progress+'%':'');row.append(name,value);box.append(row);}if(!result.printers?.length)translatedText(box,'尚未添加打印机');}\n"
"async function switchLanguage(){if(busy)return;pageLanguageChosen=true;uiEnglish=el('pageLanguage').value==='1';applyLanguage();status(statusSource);if(healthSnapshot)renderHealth(healthSnapshot);if(cfg)previewOptions(savedCfg||cfg);busy=true;updateControls();clearTimeout(autosave.timer);languageStatus('正在同步小屏语言…');\n"
"try{const result=await saveDeviceLanguage(uiEnglish?1:0);if(!portalAlive)return;if(cfg){if(cfg.revision===result.previousRevision){cfg.revision=result.revision;if(savedCfg)savedCfg.revision=result.revision;}else{autosave.blocked=true;status('配置已在软件或其他入口更新。请重新读取后再修改；未覆盖设备原配置。','error');}cfg.language=result.language;if(savedCfg)savedCfg.language=result.language;if(lastSavedFingerprint){const previous=JSON.parse(lastSavedFingerprint);previous.language=result.language;lastSavedFingerprint=fingerprint(previous);}}languageStatus('网页与小屏语言已同步');setTimeout(()=>refreshPreview(true),300);}\n"
"catch(e){if(portalAlive){languageStatus(e.message,true);if(e.conflict)autosave.blocked=true;}}finally{busy=false;if(portalAlive){updateControls();if(autosave.pending&&!autosave.blocked)autosave.timer=setTimeout(()=>autosave.flush(),250);}}}\n"
"el('pageLanguage').onchange=switchLanguage;el('languageRetry').onclick=switchLanguage;\n"
"el('read').onclick=()=>transfer(false);el('reload').onclick=()=>transfer(false);el('save').onclick=()=>transfer(true);el('saveBottom').onclick=()=>transfer(true);el('forget').onclick=()=>{if(dirty&&!confirm(t('结束授权会丢弃尚未保存的更改，继续吗？')))return;autosave.reset();authToken='';cfg=null;dirty=false;clearSecrets();el('json').textContent=t('尚未读取');updateControls();status('本次授权已结束。连接同一 Wi-Fi 后即可重新连接。');};\n"
"el('addEntity').onclick=()=>{const next=currentDraft();if(next.ha.entities.length>=6)return;next.ha.entities.push({id:'',name:''});fill(next,true);markDirty();};\n"
"function appendPrinter(formlabs=false){const next=currentDraft();if(next.printers.length>=3)return;next.printers.push({enabled:true,source_ha:!formlabs,source_formlabs:formlabs,brand:formlabs?'formlabs':'bambu',name:'',host:'',serial:formlabs?'':'c6_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8),form_client_id:'',certificate:'',trust_lan:false,status_entity:'',progress_entity:'',task_entity:'',remaining_entity:'',image_entity:'',show_status:true,show_progress:true,show_task:true,show_remaining:true,show_image:true});fill(next,true);markDirty();}\n"
"el('addPrinter').onclick=()=>appendPrinter(false);el('addFormPrinter').onclick=()=>appendPrinter(true);\n"
"for(const input of document.querySelectorAll('#options input,#options select,#options textarea'))input.oninput=markDirty;\n"
"el('theme_preset').onchange=()=>{const preset=el('theme_preset').value;if(preset==='custom')return;draftDark=preset==='dark';const palette=draftDark?themeDefaults:{background:0xEEF2F7,card:0xFFFFFF,inset:0xF3F6FA,border:0xCBD5E1,accent:0x0F766E,secondary_accent:0x2563EB,primary_text:0x0F172A,secondary_text:0x414D61,tertiary_text:0x5D6C82};for(const key of themeKeys)el('theme_'+key).value='#'+palette[key].toString(16).padStart(6,'0');el('theme_enabled').checked=true;markDirty();};\n"
"\n"
"for(const link of document.querySelectorAll('nav a[href^=\"#\"]'))link.onclick=()=>{for(const item of document.querySelectorAll('nav a'))item.removeAttribute('aria-current');link.setAttribute('aria-current','location');};\n"
"const wifiLink=document.querySelector('nav a[href=\"/\"]');if(wifiLink)wifiLink.onclick=event=>{if(busy){event.preventDefault();status('正在保存或读取配置，请完成后再切换页面。');return;}if(dirty&&!confirm(t('离开此页面会丢弃尚未保存的更改，继续吗？'))){event.preventDefault();return;}dirty=false;};\n"
"window.addEventListener('beforeunload',event=>{if(dirty||busy){event.preventDefault();event.returnValue='';}});\n"
"window.addEventListener('pagehide',()=>{portalAlive=false;autosave.reset();authToken='';cfg=null;clearSecrets();updateControls();});\n"
"window.addEventListener('pageshow',event=>{if(event.persisted){portalAlive=true;busy=false;dirty=false;updateControls();status('本次连接已结束，请重新读取配置。');readDeviceInfo();}});\n"
"async function readDeviceInfo(){try{const r=await request('/api/info');if(!r.ok)throw Error();const info=await r.json();el('deviceIP').textContent=info.ip&&info.ip!=='0.0.0.0'?info.ip:t('热点连接 · 等待联网');el('firmware').textContent=info.fw||t('C6 测试固件');}catch{el('deviceIP').textContent=t('未连接 · 请检查网络');el('firmware').textContent=t('暂不可读取');}}\n"
"// Read the display owner's canonical RGB565 frame; no simulated HTML artwork.\n"
"let previewBusy=false,previewAlive=true,previewRevision='',previewTimer,previewAbort;\n"
"function previewOptions(config){const select=el('previewCard'),previous=select.value;select.replaceChildren();\n"
"    const option=(value,label)=>{const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);};\n"
"    option('auto',t('当前画面'));if(config.clock)option('clock',t(config.clock_style===1?'圆角粗数字':'翻页钟'));\n"
"    if(config.weather)option('weather',t('天气'));if(config.diagnostics)option('diagnostics',t('设备状态'));\n"
"    if(config.ha?.enabled&&config.ha.entities.length)for(let i=0;i<Math.ceil(config.ha.entities.length/4);i++)option('ha:'+i,'Home Assistant · '+(i+1));\n"
"    if(config.printers.filter(p=>p.enabled).length>=2)option('overview',t('打印机总览'));\n"
"    config.printers.forEach((p,i)=>{if(p.enabled)option('printer:'+i,(p.source_formlabs?'Formlabs':'Bambu Lab')+' · '+(p.name||p.serial));});\n"
"    select.value=Array.from(select.options||select.children).some(o=>o.value===previous)?previous:'auto';\n"
"}\n"
"function previewPixels(bytes,rotation){if(bytes.length!==115200||![0,90,180,270].includes(rotation))throw Error(t('预览画面无效'));\n"
"    const rgba=new Uint8ClampedArray(240*240*4);for(let y=0;y<240;y++)for(let x=0;x<240;x++){\n"
"        let sx=x,sy=y;if(rotation===90){sx=y;sy=239-x;}else if(rotation===180){sx=239-x;sy=239-y;}else if(rotation===270){sx=239-y;sy=x;}\n"
"        const from=(sy*240+sx)*2,to=(y*240+x)*4,v=bytes[from]*256+bytes[from+1];rgba[to]=Math.round((v>>11)*255/31);rgba[to+1]=Math.round(((v>>5)&63)*255/63);rgba[to+2]=Math.round((v&31)*255/31);rgba[to+3]=255;\n"
"    }return rgba;\n"
"}\n"
"async function refreshPreview(force=false){if(!previewAlive||previewBusy||busy||document.hidden||!authToken)return;\n"
"    previewBusy=true;previewAbort=new AbortController();const timeout=setTimeout(()=>previewAbort?.abort(),4000);\n"
"    try{const path='/api/frame'+(!force&&previewRevision?'?rev='+encodeURIComponent(previewRevision):'');\n"
"        const r=await fetch(path,{cache:'no-store',headers:{Authorization:'Bearer '+authToken},signal:previewAbort.signal});\n"
"        if(!previewAlive)return;if(r.status===401){authToken='';updateControls();throw Error(t('请重新读取设备配置'));}if(!r.ok)throw Error(t('无法读取设备画面'));\n"
"        if(r.status!==204){const bytes=new Uint8Array(await r.arrayBuffer());if(!previewAlive)return;const canvas=el('screenPreview'),context=canvas.getContext('2d'),data=context.createImageData(240,240);data.data.set(previewPixels(bytes,Number(r.headers.get('X-Lingxi-Rotation')||0)));context.putImageData(data,0,0);}\n"
"        previewRevision=r.headers.get('X-Lingxi-Frame-Revision')||'';\n"
"        translatedText(el('previewStatus'),r.headers.get('X-Lingxi-Asleep')==='1'?'设备已休眠 · 显示休眠前画面':'设备实际画面 · 每 3 秒刷新');\n"
"    }catch{if(previewAlive)translatedText(el('previewStatus'),'预览连接中断，保留最近画面');}finally{clearTimeout(timeout);previewAbort=null;previewBusy=false;}\n"
"}\n"
"async function showPreviewCard(card){if(busy||!authToken)return false;if(dirty)return status('请先保存当前修改，再切换设备画面。','error');\n"
"    if(previewBusy){previewAbort?.abort();while(previewBusy&&previewAlive)await new Promise(resolve=>setTimeout(resolve,30));}\n"
"    const [kind,index]=card.split(':'),query=new URLSearchParams({card:kind});if(index!==undefined)query.set('index',index);previewBusy=true;\n"
"    try{const r=await request('/api/view?'+query,{method:'POST',headers:{Authorization:'Bearer '+authToken}});if(!r.ok)throw Error(t(r.status===409?'请先退出设备设置，并确认卡片已保存启用':'无法切换设备画面'));previewRevision='';}\n"
"    catch(e){translatedText(el('previewStatus'),e.message);return false;}finally{previewBusy=false;}await refreshPreview(true);return true;\n"
"}\n"
"el('previewShow').onclick=()=>showPreviewCard(el('previewCard').value);el('previewAuto').onclick=()=>showPreviewCard('auto');el('previewRefresh').onclick=()=>refreshPreview(true);\n"
"async function previewLoop(){await refreshPreview();if(previewAlive)previewTimer=setTimeout(previewLoop,3000);}previewTimer=setTimeout(previewLoop,1000);\n"
"window.addEventListener('pagehide',()=>{previewAlive=false;clearTimeout(previewTimer);previewAbort?.abort();});\n"
"window.addEventListener('pageshow',event=>{if(event.persisted){previewAlive=true;previewRevision='';clearTimeout(previewTimer);previewTimer=setTimeout(previewLoop,1000);translatedText(el('previewStatus'),'请重新读取设备配置');}});\n"
"\n"
"setupAppearance();applyLanguage();el('pageLanguage').value=uiEnglish?1:0;languageStatus('网页与小屏使用同一语言，切换后自动保存。');\n"
"el('options').addEventListener('compositionstart',()=>{autosave.composing=true;clearTimeout(autosave.timer);});el('options').addEventListener('compositionend',()=>{autosave.composing=false;markDirty();});el('options').addEventListener('focusout',()=>autosave.flush());el('brightness').addEventListener('pointerup',()=>autosave.flush());\n"
"setInterval(()=>{if(!busy&&!document.hidden)health();},10000);updateControls();readDeviceInfo();transfer(false);\n"
"</script></body></html>\n"
"\n";
